/// Parse a TOML value (string, integer, boolean, or array).
fn parse_value(text : String) -> Json raise ParseError {
  if text.is_empty() {
    raise ParseError::InvalidSyntax("empty value")
  }

  if text.starts_with("\"") {
    let s = parse_string(text)?
    Json::String(s)
  } else if text == "true" {
    Json::True
  } else if text == "false" {
    Json::False
  } else if text.starts_with("[") {
    parse_array(text)?
  } else {
    // Integer (positive, negative, or leading +)
    let n : Int = @string.from_str(text) catch {
      _ => raise ParseError::InvalidSyntax("invalid value: \{text}")
    }
    Json::Number(n.to_double(), repr=text.to_owned())
  }
}

///|
/// Parse a basic TOML string (double-quoted with escapes).
fn parse_string(text : String) -> String raise ParseError {
  if !text.starts_with("\"") || !text.ends_with("\"") {
    raise ParseError::InvalidSyntax("invalid string: \{text}")
  }
  let inner = text.sub(start=1, end=text.length() - 1)
  let mut result = StringBuilder::new()
  let mut i = 0
  let chars = inner.to_array()
  while i < chars.length() {
    let ch = chars[i]
    if ch == '\\' && i + 1 < chars.length() {
      let next = chars[i + 1]
      i = i + 2
      match next {
        '"' => result.write_char('"')
        '\\' => result.write_char('\\')
        'n' => result.write_char('\n')
        't' => result.write_char('\t')
        _ => raise ParseError::InvalidSyntax(
          "invalid escape: \\\{next}",
        )
      }
    } else {
      result.write_char(ch)
      i = i + 1
    }
  }
  result.to_string()
}

///|
/// Parse a TOML array: `[item, item, ...]`.
fn parse_array(text : String) -> Json raise ParseError {
  if !text.starts_with("[") || !text.ends_with("]") {
    raise ParseError::InvalidSyntax("invalid array: \{text}")
  }
  let inner = text.sub(start=1, end=text.length() - 1).trim()
  if inner.is_empty() {
    return Json::Array([])
  }

  // Split by commas at the top level (not inside nested strings/arrays)
  let items = split_top_level(inner)?
  let mut arr : Array[Json] = []
  for item in items {
    let trimmed = item.trim()
    if !trimmed.is_empty() {
      arr.push(parse_value(trimmed)?)
    }
  }
  Json::Array(arr)
}

///|
/// Split a string by commas at the top level (no nested awareness beyond matching quotes).
fn split_top_level(text : String) -> Array[String] raise ParseError {
  let mut parts : Array[String] = []
  let mut depth = 0
  let mut in_str = false
  let mut start = 0
  let chars = text.to_array()
  for i = 0; i < chars.length(); i = i + 1 {
    let ch = chars[i]
    if in_str {
      if ch == '\\' {
        // skip next char
        if i + 1 < chars.length() {
          i = i + 1
        }
      } else if ch == '"' {
        in_str = false
      }
    } else {
      if ch == '"' {
        in_str = true
      } else if ch == '[' {
        depth = depth + 1
      } else if ch == ']' {
        depth = depth - 1
      } else if ch == ',' && depth == 0 {
        parts.push(text.sub(start=start, end=i))
        start = i + 1
      }
    }
  }
  if start < text.length() {
    parts.push(text.sub(start=start, end=text.length()))
  }
  parts
}

///|
/// Build a nested JSON object from a flat dotted-key map.
fn build_nested_json(entries : Map[String, Json]) -> Json raise ParseError {
  let root : Map[String, Json] = Map::new()
  for key, value in entries {
    let parts = key.split(".").to_array()
    set_nested(root, parts, value)?
  }
  Json::Object(root)
}

///|
/// Recursively set a value at the given path in a map.
fn set_nested(
  map : Map[String, Json],
  path : Array[String],
  value : Json
) -> Unit raise ParseError {
  if path.length() == 1 {
    let k = path[0]
    if map.contains(k) {
      raise ParseError::DuplicateKey("duplicate key: \{k}")
    }
    map[k] = value
  } else {
    let k = path[0]
    let rest = path[1..]
    if map.contains(k) {
      match map[k] {
        Json::Object(sub) => set_nested(sub, rest, value)?
        _ =>
          raise ParseError::InvalidSyntax(
            "\{k} is not a table",
          )
      }
    } else {
      let sub : Map[String, Json] = Map::new()
      map[k] = Json::Object(sub)
      set_nested(sub, rest, value)?
    }
  }
}
