///|
/// Error type for TOML parsing errors.
suberror ParseError {
  InvalidSyntax(String)
  DuplicateKey(String)
} derive(Debug)

///|
/// Parse TOML text into a `Json` value.
///
/// Supports:
/// - Comments (`#`)
/// - Blank lines and whitespace
/// - Bare keys and dotted keys
/// - Tables (`[table]`, `[table.nested]`)
/// - Basic strings with `\"`, `\\`, `\n`, `\t` escapes
/// - Integers, booleans, and arrays of those values
/// - Duplicate-key detection
pub fn parse_toml(text : String) -> Json raise ParseError {
  let lines = text.split("\n").to_array()
  let mut current_table : Array[String] = []
  let entries : Map[String, Json] = Map([])

  for i = 0; i < lines.length(); i = i + 1 {
    let raw = lines[i]
    let trimmed_view = raw.trim()
    if trimmed_view.is_empty() || trimmed_view.starts_with("#") {
      continue
    }
    let trimmed = trimmed_view.to_owned()

    if trimmed.starts_with("[") && !trimmed.starts_with("[[") {
      // Table header
      if !trimmed.ends_with("]") {
        raise ParseError::InvalidSyntax(
          "unclosed table header: " + trimmed,
        )
      }
      let inner = trimmed
        .sub(start=1, end=trimmed.length() - 1)
        .trim()
        .to_owned()
      current_table = inner.split(".").map(fn(v) { v.to_owned() }).to_array()
      continue
    }

    // Key = value
    let eq_pos = trimmed.find("=")
    if eq_pos.is_none() {
      raise ParseError::InvalidSyntax(
        "expected key = value, got: " + trimmed,
      )
    }
    let eq = eq_pos.unwrap()
    let key_str = trimmed.sub(start=0, end=eq).trim().to_owned()
    let val_str = trimmed.sub(start=eq + 1, end=trimmed.length()).trim().to_owned()

    let key_parts = key_str.split(".").map(fn(v) { v.to_owned() }).to_array()
    let full_path : Array[String] = current_table + key_parts
    let full_key = full_path.join(".")

    if entries.contains(full_key) {
      raise ParseError::DuplicateKey("duplicate key: " + full_key)
    }

    let value = parse_value(val_str)
    entries[full_key] = value
  }

  build_nested_json(entries)
}

